/// <summary>
/// Extension of LogisticsAddressState Table
/// </summary>
[ExtensionOf(tableStr(LogisticsAddressState))]
final class METLogisticsAddressState_Extension
{
}

Method.Source:
/// <summary>
/// Decides whether the value of a specific field is valid.
/// </summary>
/// <param name="_fieldName">
/// The specified name of field to validate.
/// </param>
/// <param name="_arrayIndex">
/// THe specified array index for the field; optional.
/// </param>
/// <returns>
/// true if the validation passes; otherwise, false.
/// </returns>
/// <remarks>
/// Validates the <c>METStatePrefix</c> field.  Returns true if the field contains only digits; otherwise, displays an error message and returns false.
/// </remarks>
public boolean validateFieldValue(FieldName _fieldName, int _arrayIndex)
{
    boolean         ret;
    
    ret = next validateFieldValue(_fieldName, _arrayIndex);
    
    if (ret)
    {
        switch (_fieldName)
        {
            case fieldStr(LogisticsAddressState, METStatePrefix) :
                
                if (strlen(int2str(this.METStatePrefix)) > 1)
                {
                    ret = checkFailed("@MET:METStatePrefixCheck");
                }
                break;
        }
    }
    
    return ret;
}

    /// <summary>
    /// New lookup method to show states based on country parameter
    /// </summary>
    /// <param name = "_formControl">Form control</param>
    /// <param name = "_countryRegionId">Country to filter</param>
    public static void METLookupState(FormControl _formControl, LogisticsAddressCountryRegionId _countryRegionId)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(LogisticsAddressState), _formControl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(LogisticsAddressState));
        QueryBuildRange         queryBuildRange;

        sysTableLookup.addLookupfield(fieldNum(LogisticsAddressState, StateId));
        sysTableLookup.addLookupfield(fieldNum(LogisticsAddressState, CountryRegionId));        
        sysTableLookup.addLookupfield(fieldNum(LogisticsAddressState, Name));
  
        queryBuildRange = queryBuildDataSource.addRange(fieldNum(LogisticsAddressState, CountryRegionId));
        queryBuildRange.value(queryValue(_countryRegionId));
       
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// Validate the state using the company info country (primary address or business address)
    /// </summary>
    /// <param name = "_stateId">State Id</param>
    /// <returns>true if the state is valid for the country; otherwise, false</returns>
    public static boolean METValidateStateId(LogisticsAddressStateId _stateId)
    {    
        boolean ret = true;

        LogisticsAddressCountryRegionId countryRegionId = CompanyInfo::find().METCountryRegionId();
        if (!LogisticsAddressState::exist(countryRegionId, _stateId))
        {
            ret = checkFailed(strFmt("@SYS304909", _stateId, fieldId2PName(tableNum(LogisticsAddressState), fieldNum(LogisticsAddressState, StateId)), tableId2PName(tableNum(LogisticsAddressState))));
        }

        return ret;
    }
